-- Conservative rollback: only before any v5 grant edit or enabled full-accounting grant.
BEGIN;SET LOCAL ROLE celebix_saas_owner;SET LOCAL lock_timeout='5s';
SELECT pg_advisory_xact_lock(hashtextextended('saas.accounting.release249',0));
LOCK TABLE saas.in_store_staff_grants IN SHARE ROW EXCLUSIVE MODE;
DO $guard$DECLARE r record;BEGIN
 IF EXISTS(SELECT 1 FROM saas.in_store_staff_grants WHERE can_manage_accounting) OR EXISTS(SELECT 1 FROM saas.in_store_operations WHERE operation_kind='set_staff_v5') OR EXISTS(SELECT 1 FROM saas.in_store_sales WHERE status IN('payment_pending','payment_received')) OR EXISTS(SELECT 1 FROM saas.merchant_provider_jobs WHERE record_kind='invoice_integration' AND status IN('queued','running')) THEN RAISE EXCEPTION 'ACCOUNTING249_ROLLBACK_IN_USE';END IF;
 IF (SELECT count(*)FROM saas.accounting249_original_functions)<>5 THEN RAISE EXCEPTION 'ACCOUNTING249_ROLLBACK_BACKUP';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.accounting249_base_authority_error(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone)') AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='c74e07d2c303db3ba26d898c0187701e51b5144c149c5dd5d6a664f12b02b824' AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner}'::aclitem[] AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[] AND p.prosecdef AND p.provolatile='s' AND NOT p.proisstrict AND p.proparallel='u') THEN RAISE EXCEPTION 'ACCOUNTING249_NEW_FUNCTION:%','saas.accounting249_base_authority_error(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone)';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.accounting249_can_manage(uuid,uuid)') AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='7496a296daebc9917c747597fc728b35e552bca2b0344af10cdb0af7d33587c1' AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner}'::aclitem[] AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[] AND p.prosecdef AND p.provolatile='s' AND NOT p.proisstrict AND p.proparallel='u') THEN RAISE EXCEPTION 'ACCOUNTING249_NEW_FUNCTION:%','saas.accounting249_can_manage(uuid,uuid)';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.accounting_access_read(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone)') AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='781732d4593ed05afd7ac1d345c39a065de69c99ca377fbe78401ed6c87186f0' AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner,celebix_saas_app=X/celebix_saas_owner}'::aclitem[] AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[] AND p.prosecdef AND p.provolatile='s' AND NOT p.proisstrict AND p.proparallel='u') THEN RAISE EXCEPTION 'ACCOUNTING249_NEW_FUNCTION:%','saas.accounting_access_read(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone)';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.in_store_staff_projection_v5(uuid,uuid)') AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='7f6997dc2594755a5050b496dd67cc5cc820b0d296f4762ce04a6af6bbdd0652' AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner}'::aclitem[] AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[] AND p.prosecdef AND p.provolatile='s' AND NOT p.proisstrict AND p.proparallel='u') THEN RAISE EXCEPTION 'ACCOUNTING249_NEW_FUNCTION:%','saas.in_store_staff_projection_v5(uuid,uuid)';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.in_store_sales_list_staff_v5(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone)') AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='2d8a931cb5dbdd9e107c1b16e50839440398c33e1ca06aff0ab201adc108d4e2' AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner,celebix_saas_app=X/celebix_saas_owner}'::aclitem[] AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[] AND p.prosecdef AND p.provolatile='s' AND NOT p.proisstrict AND p.proparallel='u') THEN RAISE EXCEPTION 'ACCOUNTING249_NEW_FUNCTION:%','saas.in_store_sales_list_staff_v5(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone)';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.in_store_sales_recover_staff_v5(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,uuid,text)') AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='7a8604744a5f97cb8c994a344cb3c28f91a65017b317042e238b3a68a28d239a' AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner,celebix_saas_app=X/celebix_saas_owner}'::aclitem[] AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[] AND p.prosecdef AND p.provolatile='s' AND NOT p.proisstrict AND p.proparallel='u') THEN RAISE EXCEPTION 'ACCOUNTING249_NEW_FUNCTION:%','saas.in_store_sales_recover_staff_v5(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,uuid,text)';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.in_store_sales_set_staff_v5(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,uuid,text,uuid,bigint,boolean,uuid[],integer,boolean,boolean,boolean,boolean)') AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='b0480803ef81353237a39072ccb1ad14555ab715e321df8fa37345fc00024d82' AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner,celebix_saas_app=X/celebix_saas_owner}'::aclitem[] AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[] AND p.prosecdef AND p.provolatile='v' AND NOT p.proisstrict AND p.proparallel='u') THEN RAISE EXCEPTION 'ACCOUNTING249_NEW_FUNCTION:%','saas.in_store_sales_set_staff_v5(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,uuid,text,uuid,bigint,boolean,uuid[],integer,boolean,boolean,boolean,boolean)';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.accounting_invoice_profiles_read(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,text)') AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='63df62014a4adc08820f8eb46a07d78f667e7581970ad161f319f2cd4aa4e048' AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner,celebix_saas_app=X/celebix_saas_owner}'::aclitem[] AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[] AND p.prosecdef AND p.provolatile='s' AND NOT p.proisstrict AND p.proparallel='u') THEN RAISE EXCEPTION 'ACCOUNTING249_NEW_FUNCTION:%','saas.accounting_invoice_profiles_read(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,text)';END IF;
 FOR r IN SELECT * FROM saas.accounting249_original_functions LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=r.function_oid AND p.oid=to_regprocedure(r.signature) AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')=r.published_sha256 AND p.proowner=r.function_owner AND p.proacl IS NOT DISTINCT FROM r.function_acl AND p.proconfig IS NOT DISTINCT FROM r.function_config AND p.prosecdef=r.function_security AND p.provolatile=r.function_volatility AND p.proisstrict=r.function_strict AND p.proparallel=r.function_parallel) OR encode(sha256(convert_to(r.definition,'UTF8')),'hex')<>r.original_sha256 THEN RAISE EXCEPTION 'ACCOUNTING249_ROLLBACK_SOURCE_DRIFT:%',r.signature;END IF;
 END LOOP;
 FOR r IN SELECT * FROM saas.accounting249_original_functions LOOP EXECUTE r.definition;IF encode(sha256(convert_to(pg_get_functiondef(to_regprocedure(r.signature)),'UTF8')),'hex')<>r.original_sha256 THEN RAISE EXCEPTION 'ACCOUNTING249_RESTORE_MISMATCH:%',r.signature;END IF;END LOOP;
END $guard$;
DROP FUNCTION saas.accounting_invoice_profiles_read(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,text);
DROP FUNCTION saas.in_store_sales_set_staff_v5(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,uuid,text,uuid,bigint,boolean,uuid[],integer,boolean,boolean,boolean,boolean);
DROP FUNCTION saas.in_store_sales_recover_staff_v5(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,uuid,text);
DROP FUNCTION saas.in_store_sales_list_staff_v5(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone);
DROP FUNCTION saas.in_store_staff_projection_v5(uuid,uuid);
DROP FUNCTION saas.accounting_access_read(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone);
DROP FUNCTION saas.accounting249_can_manage(uuid,uuid);
DROP FUNCTION saas.accounting249_base_authority_error(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone);
ALTER TABLE saas.in_store_staff_grants DROP COLUMN can_manage_accounting;
DROP TABLE saas.accounting249_original_functions;
DO $payment$BEGIN
 IF saas.built_in_payment_methods_preflight() IS DISTINCT FROM true OR saas.payment_provider_keyed_lifecycle_preflight() IS DISTINCT FROM true OR saas.iyzico_iframe_tenant_activation_runtime_preflight() IS DISTINCT FROM true OR saas.quick_order_hosted_payment_authority_preflight() IS DISTINCT FROM true OR saas.shipping_provider_preflight() IS DISTINCT FROM true THEN RAISE EXCEPTION 'ACCOUNTING249_PAYMENT_PREFLIGHT';END IF;
END $payment$;COMMIT;
